// Object literal
const user = {
  name: 'Prashant',
  age: 27,
  email: 'prashant@example.com',
  isActive: true,
  skills: ['JavaScript', 'CSS', 'HTML'],  // array as property value

  // Method — function as property
  greet() {
    return `Hi, I'm ${this.name}!`;
  },
};

console.log(user.name);       // 'Prashant'
console.log(user['email']);   // 'prashant@example.com'
console.log(user.greet());   // 'Hi, I'm Prashant!'

const user = { name: 'Ana', age: 28 };

// Add property
user.role = 'admin';

// Update property
user.age = 29;

// Delete property
delete user.role;

// Check if property exists
console.log('name' in user);       // true
console.log('role' in user);       // false
console.log(user.hasOwnProperty('name')); // true

const user = { name: 'Prashant', age: 27, city: 'Mumbai' };

// Destructuring assignment
const { name, age } = user;
console.log(name, age);  // 'Prashant' 27

// Rename on extraction
const { name: fullName, city: location = 'Unknown' } = user;
console.log(fullName, location);  // 'Prashant' 'Mumbai'

// In function parameters — very common pattern
function displayUser({ name, age, city = 'N/A' }) {
  console.log(`${name} (${age}) — ${city}`);
}
displayUser(user);  // 'Prashant (27) — Mumbai'

const base = { theme: 'dark', lang: 'en' };
const overrides = { lang: 'hi', fontSize: 16 };

// Spread — merge objects (later keys overwrite earlier)
const config = { ...base, ...overrides };
console.log(config);  // { theme: 'dark', lang: 'hi', fontSize: 16 }

// Shallow clone
const copy = { ...base };

// Object static methods
Object.keys(user);    // ['name', 'age', 'city']
Object.values(user);  // ['Prashant', 27, 'Mumbai']
Object.entries(user); // [['name','Prashant'],['age',27],['city','Mumbai']]

// Iterate over object
for (const [key, value] of Object.entries(user)) {
  console.log(`${key}: ${value}`);
}
